if (
    type(poly_order) is int
    and self.vandermonde is not None
    and poly_order >= 0
    and poly_order == self.poly_order
):
    return

poly_order = _check_scalar_variable(
    poly_order, allow_zero=True, variable_name='polynomial order', dtype=int
)
if self.vandermonde is None or poly_order > self.poly_order:
    mapped_x = np.polynomial.polyutils.mapdomain(
        x, x_domain, np.array([-1., 1.])
    )
    self.vandermonde = np.polynomial.polynomial.polyvander(mapped_x, poly_order)
    self.pinv_stale = True
elif poly_order < self.poly_order:
    self.vandermonde = self.vandermonde[:, :poly_order + 1]
    self.pinv_stale = True

self.poly_order = poly_order

weight_array = _check_optional_array(
    self._size, weights, copy_input=copy_weights, check_finite=self._check_finite
)
if self._sort_order is not None and weights is not None:
    weight_array = weight_array[self._sort_order]

if calc_vander:
    if self._polynomial is None:
        self._polynomial = _PolyHelper(self.x, self.x_domain, poly_order)
    else:
        self._polynomial.recalc_vandermonde(self.x, self.x_domain, poly_order)

if not calc_pinv:
    return y, weight_array
elif not calc_vander:
    raise ValueError('if calc_pinv is True, then calc_vander must also be True')

if weights is None:
    pseudo_inverse = self._polynomial.pseudo_inverse
else:
    vandermonde = self._polynomial.vandermonde
    cache_key = None
    entry_bytes = 2 * vandermonde.nbytes + weight_array.nbytes
    if (
        weight_array.dtype == np.dtype('float64')
        and vandermonde.dtype == np.dtype('float64')
        and entry_bytes <= 512 * 1024
    ):
        cache_key = (
            vandermonde.shape, vandermonde.strides, vandermonde.dtype.str,
            weight_array.shape, weight_array.strides, weight_array.dtype.str,
            vandermonde.tobytes(), weight_array.tobytes()
        )
    cache = getattr(self, '_weighted_polynomial_pinv_entries', None)
    if cache is None:
        cache = []
        self._weighted_polynomial_pinv_entries = cache
    hit = None
    if cache_key is not None:
        for index, entry in enumerate(cache):
            if entry[0] == cache_key:
                hit = index
                break
    if hit is not None:
        entry = cache.pop(hit)
        cache.append(entry)
        pseudo_inverse = entry[1].copy(order='K')
    else:
        pseudo_inverse = np.linalg.pinv(
            np.sqrt(weight_array)[:, None] * vandermonde
        )
        if cache_key is not None and (
            pseudo_inverse.flags.c_contiguous or pseudo_inverse.flags.f_contiguous
        ):
            entry_bytes = (
                len(cache_key[-2]) + len(cache_key[-1]) + pseudo_inverse.nbytes
            )
            if entry_bytes <= 512 * 1024:
                retained_bytes = sum(entry[2] for entry in cache)
                while cache and (
                    len(cache) >= 4 or retained_bytes + entry_bytes > 512 * 1024
                ):
                    retained_bytes -= cache.pop(0)[2]
                cache.append((cache_key, pseudo_inverse.copy(order='K'), entry_bytes))

return y, weight_array, pseudo_inverse
